static int32_t lvgl_app_backlight_clamp(int32_t percent)
{
  int32_t min_percent = CONFIG_LVGL_APP_BACKLIGHT_MIN_PERCENT;

  if (min_percent < 1)
    {
      min_percent = 1;
    }
  else if (min_percent > 100)
    {
      min_percent = 100;
    }

  if (percent < 0)
    {
      return min_percent;
    }

  if (percent > 100)
    {
      return 100;
    }

  if (percent < min_percent)
    {
      return min_percent;
    }

  return percent;
}

#ifdef CONFIG_PWM
static uint32_t lvgl_app_backlight_read_pwm(uint32_t offset)
{
  return *(volatile uint32_t *)(uintptr_t)(LVGL_APP_AIC_PWM_BASE + offset);
}

static void lvgl_app_backlight_write_pwm(uint32_t offset, uint32_t value)
{
  *(volatile uint32_t *)(uintptr_t)(LVGL_APP_AIC_PWM_BASE + offset) = value;
  __asm__ __volatile__("" : : : "memory");
}

static uint32_t lvgl_app_backlight_channel_offset(int channel,
                                                  uint32_t reg)
{
  return LVGL_APP_AIC_PWM_CHANNEL_BASE +
         (uint32_t)channel * LVGL_APP_AIC_PWM_CHANNEL_STRIDE + reg;
}

static int lvgl_app_backlight_pwm_channel(void)
{
  const char *path = CONFIG_LVGL_APP_BACKLIGHT_PWM_PATH;
  int channel = -1;
  int value = -1;
  int i;

  for (i = 0; path[i] != '\0'; i++)
    {
      if (path[i] >= '0' && path[i] <= '9')
        {
          if (value < 0)
            {
              value = 0;
            }

          value = value * 10 + path[i] - '0';
        }
      else if (value >= 0)
        {
          channel = value;
          value = -1;
        }
    }

  if (value >= 0)
    {
      channel = value;
    }

  if (channel < 0 || channel >= LVGL_APP_AIC_PWM_MAX_CHANNELS)
    {
      return -ENODEV;
    }

  return channel;
}

static int lvgl_app_backlight_calc_period(uint32_t frequency,
                                           uint32_t *div,
                                           uint32_t *period)
{
  uint32_t candidate;
  uint32_t ticks;

  if (frequency == 0 || div == NULL || period == NULL)
    {
      return -EINVAL;
    }

  for (candidate = 0; candidate <= 0x0fffu; candidate++)
    {
      ticks = (LVGL_APP_AIC_PWM_CLK_RATE / (candidate + 1u)) / frequency;
      if (ticks > 0 && ticks <= 0x10000u)
        {
          *div = candidate;
          *period = ticks - 1u;
          return 0;
        }
    }

  return -ERANGE;
}

static uint32_t lvgl_app_backlight_compare(uint32_t period,
                                           int32_t percent)
{
  uint64_t compare;

  compare = ((uint64_t)period * (uint64_t)percent + 50u) / 100u;
  if (percent >= 100 && compare == period)
    {
      compare++;
    }

  return (uint32_t)compare;
}

static int lvgl_app_backlight_apply_direct(int32_t percent)
{
  uint32_t div;
  uint32_t period;
  uint32_t compare;
  uint32_t offset;
  uint32_t reg;
  int channel;
  int ret;

  channel = lvgl_app_backlight_pwm_channel();
  if (channel < 0)
    {
      return channel;
    }

  ret = lvgl_app_backlight_calc_period(
    CONFIG_LVGL_APP_BACKLIGHT_DIRECT_PWM_FREQUENCY, &div, &period);
  if (ret < 0)
    {
      return ret;
    }

  compare = lvgl_app_backlight_compare(period, percent);

  reg = lvgl_app_backlight_read_pwm(LVGL_APP_AIC_PWM_CTL);
  lvgl_app_backlight_write_pwm(LVGL_APP_AIC_PWM_CTL,
                               reg | LVGL_APP_AIC_PWM_CTL_EN);

  reg = lvgl_app_backlight_read_pwm(LVGL_APP_AIC_PWM_CKCTL);
  lvgl_app_backlight_write_pwm(LVGL_APP_AIC_PWM_CKCTL,
                               reg | (1u << channel));

  offset = lvgl_app_backlight_channel_offset(channel,
                                             LVGL_APP_AIC_PWM_TBCTL);
  reg = lvgl_app_backlight_read_pwm(offset);
  reg &= ~(LVGL_APP_AIC_PWM_TBCTL_CLKDIV_MASK |
           LVGL_APP_AIC_PWM_TBCTL_MODE_MASK);
  reg |= div << LVGL_APP_AIC_PWM_TBCTL_CLKDIV_SHIFT;
  lvgl_app_backlight_write_pwm(offset, reg);

  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_CMPCTL),
    LVGL_APP_AIC_PWM_CMPCTL_SHADOW_ZRO_PRD);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_TBPRD),
    period);
  lvgl_app_backlight_write_pwm(
    lvgl_app_backlight_channel_offset(channel, LVGL_APP_AIC_PWM_CMPA),
    compare);

